import{z as E,x as p,o as i,c as A,q as n,j as t,D as r,d as s,s as o,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const v=JSON.parse('{"title":"指纹与 Freivalds","description":"","frontmatter":{"title":"指纹与 Freivalds","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fingerprinting-freivalds.md","filePath":"cs/fingerprinting-freivalds.md","lastUpdated":1791413859000}'),B={name:"cs/fingerprinting-freivalds.md"};function C(D,a,h,m,c,f){const l=p("Mermaid");return i(),A("div",null,[a[2]||(a[2]=n('<h1 id="指纹与-freivalds" tabindex="-1">指纹与 Freivalds <a class="header-anchor" href="#指纹与-freivalds" aria-label="Permalink to &quot;指纹与 Freivalds&quot;">​</a></h1><div class="epigraph"><p>把长对象映射到随机模的短指纹；Freivalds 用随机向量 $O(n^2)$ 检验矩阵乘，错概率 $1/|S|$。</p><footer>—— 据 Freivalds, Fast Probabilistic Algorithms, 1977；Motwani and Raghavan；CLRS 第 5、32 章整理</footer></div><p>上一课<a href="/cs/las-vegas-monte-carlo">Las Vegas 与 Monte Carlo</a>钉了两类随机算法的合同；本课主题是指纹：把串、多项式、矩阵映射成随机的短摘要，相等检验变成比对指纹——碰撞只是可控概率的假阳性。缺口是 Freivalds：检验 \\(AB=C\\) 不必再做一遍 \\(O(n^3)\\) 的乘法。本课不重写 Karatsuba；后课随机游走与混合时间。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三个实例。多项式恒等：随机取点 \\(x\\)，Schwartz–Zippel 给出界——\\(d\\) 次多项式在有限集 \\(S\\) 上撞根的概率 \\(\\le d/|S|\\)，相等则必真，不等则大概率现形。串匹配的 Rabin–Karp 同精神：模随机素数的滚动哈希当指纹。Freivalds：随机向量 \\(r\\in\\{0,1\\}^n\\)，检验 \\(A(Br)\\stackrel{?}{=}Cr\\)，三次矩阵–向量乘共 \\(O(n^2)\\)；若 \\(AB\\neq C\\) 却判等的错概率 \\(\\le 1/2\\)，换成大域取值更小，重复 \\(k\\) 次错概率指数下降。</p><p>缺口是「检验」这个任务，不是计算乘积本身。</p><h3 id="不是密码学碰撞抗性" tabindex="-1">不是密码学碰撞抗性 <a class="header-anchor" href="#不是密码学碰撞抗性" aria-label="Permalink to &quot;不是密码学碰撞抗性&quot;">​</a></h3><p>这不是密码学的碰撞抗性：指纹的安全性来自随机数在对手选定输入<strong>之后</strong>才抽取——对手若能看到你的随机数再选输入，界即失效。自适应对手要另论。</p><p><span class="marginnote">常见误区：初学者把这里的指纹当 CRC 或固定哈希函数用。指纹的抗碰撞不来自函数本身的设计，而来自「随机数在见到输入之后才抽」；若对手先知道你的随机点再挑输入，\\(d/|S|\\) 这条界就守不住了。</span></p><p><span class="marginnote">Freivalds 1977。Schwartz–Zippel。Rabin–Karp。后课混合时间是马尔可夫，不是指纹。</span></p><p><span class="marginnote">数字实例：单轮判错的概率 ≤ 1/2。独立地换随机向量重复 5 轮，全错的概率 ≤ (1/2)^5 = 1/32 ≈ 3%；重复 20 轮就低于百万分之一。这就是「重复 k 次错概率指数下降」的具体含义——每加一轮，错误率直接减半。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>套路一致：选随机点或随机向量、模大素数防溢出；判等则接受（可能错），判不等则断言不等（必真）或再试一轮。要 Las Vegas 式的确定性答案，就证伪即重试直到收敛。</p>',13)),(i(),t(d,null,{default:r(()=>[o(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E5%A4%9A%E9%A1%B9%E5%BC%8F%20%2F%20%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20FP%5B%22%E9%9A%8F%E6%9C%BA%E6%8C%87%E7%BA%B9%22%5D%0A%20%20FP%20--%3E%20EQ%5B%22%E7%9B%B8%E7%AD%89%EF%BC%9FMC%22%5D%0A%20%20AB%5B%22AB%20vs%20C%22%5D%20--%3E%20FR%5B%22Freivalds%20A(Br)%3DCr%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"实现注意：滚动哈希的乘加要用模运算防溢出，模数取大素数。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制一句话：非零对象在随机投影下很少变零。线性代数版：\\(D=AB-C\\neq 0\\) 时 \\(Dr=0\\) 要求 \\(r\\) 落进 \\(D\\) 的零空间，随机 \\(r\\) 撞进去的概率小；多项式版：非零 \\(d\\) 次多项式至多 \\(d\\) 个根。指纹由此把「相等检验」整体变成 Monte Carlo。与 NTT 对照：NTT 是精确卷积，指纹是概率检验，一个算一个验。与哈希表对照：指纹可当键但带碰撞概率，哈希表靠冲突解决而非随机化。",-1)),(i(),t(d,null,{default:r(()=>[o(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E9%9A%8F%E6%9C%BA%E5%8F%96%20r%22%5D%20--%3E%20C1%5B%22%E7%AE%97%20Br%22%5D%0A%20%20C1%20--%3E%20C2%5B%22%E7%AE%97%20A(Br)%22%5D%0A%20%20R%20--%3E%20C3%5B%22%E7%AE%97%20Cr%22%5D%0A%20%20C2%20--%3E%20CMP%7B%22A(Br)%20%3D%20Cr%20%3F%22%7D%0A%20%20C3%20--%3E%20CMP%0A%20%20CMP%20--%3E%7C%22%E4%B8%8D%E7%AD%89%22%7C%20NO%5B%22%E6%96%AD%E8%A8%80%20AB%20%E2%89%A0%20C%2C%20%E5%BF%85%E7%9C%9F%22%5D%0A%20%20CMP%20--%3E%7C%22%E7%9B%B8%E7%AD%89%22%7C%20ACC%5B%22%E6%8E%A5%E5%8F%97%E7%9B%B8%E7%AD%89%2C%20%E5%8D%95%E8%BD%AE%E9%94%99%E7%8E%87%20%E2%89%A4%201%2F2%22%5D%0A%20%20ACC%20--%3E%20REP%5B%22%E6%8D%A2%20r%20%E9%87%8D%E5%A4%8D%20k%20%E8%BD%AE%E5%8E%8B%E4%BD%8E%E9%94%99%E7%8E%87%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">直觉类比：把 \\(D=AB-C\\) 想成一张藏着「证据」的网，随机向量 \\(r\\) 是撒出去的球。错误只发生在球恰好落进 \\(D\\) 的零空间这条缝里——缝隙只占平面很小一块，随机撒球几乎不可能正中，所以判错才罕见且可控。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写密码学哈希函数，不写 PCP 定理里的指纹。后课默认：\\(O(n^2)\\) 检验矩阵乘用 Freivalds。下一课随机游走与混合。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指纹把相等检验变成 MC。</li><li>Freivalds \\(O(n^2)\\) 检验乘。</li><li>Schwartz–Zippel 管多项式。</li><li>出处：Freivalds, 1977；Motwani–Raghavan。</li></ul>',5))])}const u=E(B,[["render",C]]);export{v as __pageData,u as default};
